___CSS_LOADER_EXPORT___.push([module.id, `.sea-toys-page {
  min-height: 70vh;
  padding: 64px 0 80px;
  background: linear-gradient(180deg, #f6fbff 0%, #ffffff 100%);
}

.sea-toys-shell {
  max-width: 1120px;
}

.sea-toys-head {
  max-width: 820px;
  margin-bottom: 2rem;
}

.sea-toys-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.25rem;
}

.sea-toy-card {
  display: flex;
  gap: 1rem;
  padding: 1.35rem;
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 18px 45px rgba(15, 66, 102, 0.1);
  border: 1px solid rgba(15, 66, 102, 0.08);
}

.sea-toy-icon {
  width: 3.4rem;
  height: 3.4rem;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: #eaf6ff;
  font-size: 1.7rem;
  flex: 0 0 auto;
}

.sea-toy-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.sea-toy-card h2 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
}

.sea-toy-card p {
  margin: 0;
  color: #476070;
  line-height: 1.55;
}

.sea-toy-card small {
  display: block;
  margin-top: 0.75rem;
  font-weight: 700;
  color: #0b5b8c;
}

.sea-toy-badge {
  border-radius: 999px;
  padding: 0.28rem 0.7rem;
  background: #e8f7ef;
  color: #1f7a43;
  font-size: 0.78rem;
  font-weight: 800;
  white-space: nowrap;
}

.sea-toy-badge.optional {
  background: #fff4df;
  color: #9b5a00;
}

.sea-toys-note {
  margin-top: 1.5rem;
  padding: 1.25rem 1.5rem;
  border-radius: 22px;
  background: #0b3551;
  color: white;
}

.sea-toys-note p {
  margin: 0.35rem 0 0;
  color: rgba(255, 255, 255, 0.82);
}

@media (max-width: 820px) {
  .sea-toys-grid {
    grid-template-columns: 1fr;
  }
  .sea-toy-card {
    flex-direction: column;
  }
  .sea-toy-title-row {
    flex-direction: column;
  }
